import{entityInstance}from"../entity/token.js";const tokenMap=new Map;export async function init(){const t=await entityInstance.findAll();tokenMap.clear(),t.forEach(t=>{tokenMap.set(t.token,t.get({plain:!0}))})}export function list(t){const n=t.page||1,e=t.size||15;return entityInstance.findAndCountAll({offset:(n-1)*e,limit:e}).then(t=>({list:t.rows.map(t=>t.get({plain:!0})),total:t.count,page:n,size:e}))}export function allList(){return entityInstance.findAll().then(t=>t.map(t=>t.get({plain:!0})))}export async function filter(t){return(await allList()).filter(t)}export async function findByToken(t){const n=await entityInstance.findOne({where:{token:t}});return n&&n.get({plain:!0})||void 0}export async function find(t){return(await allList()).find(t)}export async function findSync(t){return(await allList()).find(t)}export async function add(t){const n=await entityInstance.create(t);return t?.token&&tokenMap.set(t.token,{...t}),n}export async function update(t,n){const e=n?.token,o=await t.update(n);e&&tokenMap.delete(t.token);const a=t.get({plain:!0});return tokenMap.set(a.token,a),o}export async function delete_(t){const n=Array.isArray(t)?t:[t];for(const t of n)t?.token&&tokenMap.delete(t.token);const e=n.map(t=>t.token).filter(Boolean);return 0===e.length||await entityInstance.destroy({where:{token:e}}),n.length}export function verifyToken(t){if(!t)return{state:!1,msg:"验证失败: 请携带参数 token"};const n=t.split("-|-")[1],e=tokenMap.get(t);return e&&e.userUId===n?{state:!0,uId:e.userUId,userName:e.userName,userRole:e.userRole}:{state:!1,msg:"验证失败: 该token无效"}}